(9001,'之','1','zhī','丶',3,'PPPP','[{"def":"代词，代指人/事/物，可译为“他/它/这”。","example":"学而时习之。"},{"def":"助词，用于主谓之间，取消句子独立性。","example":"大道之行也。"},{"def":"助词，的。","example":"水陆草木之花。"},{"def":"动词，往，到。","example":"辍耕之垄上。"}]','seed',0),
(9002,'而','1','ér','而',6,'DMJJ','[{"def":"连词，表并列，可译为“并且/又”。","example":"温故而知新。"},{"def":"连词，表转折，可译为“但是/却”。","example":"人不知而不愠。"},{"def":"连词，表承接，顺承。","example":"择其善者而从之。"},{"def":"代词，你/你的。","example":"而翁归。"}]','seed',0),
